#include <LiquidCrystal.h>
#include <Servo.h>

#define EMERGENCY_BUTTON 2
#define ECHO_PIN 3
#define TRIG_PIN 4
#define BUZZER 5
#define GAS_DO 6

#define LCD_D7 7
#define LCD_D6 8
#define LCD_D5 9
#define LCD_D4 10
#define LCD_EN 11
#define LCD_RS 12

#define GREEN_LED 13

#define GAS_AO A0
#define TEMP_SENSOR A1
#define START_BUTTON A2
#define RED_LED A3
#define SERVO_PIN A4
#define POT A5

#define STEP_PIN 0
#define DIR_PIN 1

LiquidCrystal lcd(LCD_RS, LCD_EN, LCD_D4, LCD_D5, LCD_D6, LCD_D7);

Servo gateServo;

volatile bool emergency = false;

unsigned long lastSensorTime = 0;
unsigned long lastStepTime = 0;
unsigned long lastLcdTime = 0;
unsigned long lastButtonTime = 0;

bool systemRunning = false;
bool motorDirection = true;
bool stepState = LOW;

bool lcdScreen = false;

float distance = 0;
int gasValue = 0;
int tempValue = 0;
int speedValue = 0;

void emergencyStop()
{
  emergency = true;
  systemRunning = false;
}

float readDistance()
{
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);

  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);

  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  if (duration == 0)
  {
    return 400;
  }

  return duration * 0.0343 / 2;
}

void controlStepper()
{
  if (!systemRunning || emergency)
  {
    digitalWrite(STEP_PIN, LOW);
    return;
  }

  digitalWrite(DIR_PIN, motorDirection);

  if (speedValue < 10)
  {
    digitalWrite(STEP_PIN, LOW);
    return;
  }

  unsigned long stepInterval = map(
    speedValue,
    10,
    255,
    2000,
    300
  );

  unsigned long currentMicros = micros();

  if (currentMicros - lastStepTime >= stepInterval)
  {
    lastStepTime = currentMicros;

    stepState = !stepState;

    digitalWrite(STEP_PIN, stepState);
  }
}

void showNormal()
{
  digitalWrite(GREEN_LED, HIGH);
  digitalWrite(RED_LED, LOW);

  noTone(BUZZER);

  gateServo.write(systemRunning ? 90 : 0);
}

void showWarning()
{
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(RED_LED, LOW);

  if (systemRunning)
  {
    gateServo.write(45);
  }
  else
  {
    gateServo.write(0);
  }
}

void showDanger()
{
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(RED_LED, HIGH);

  tone(BUZZER, 2000);

  gateServo.write(0);
}

void updateLCD()
{
  lcd.clear();

  if (emergency)
  {
    lcd.setCursor(0, 0);
    lcd.print("EMERGENCY STOP");

    lcd.setCursor(0, 1);
    lcd.print("SAFETY STOP");

    return;
  }

  bool danger =
    gasValue > 700 &&
    tempValue > 70 &&
    digitalRead(GAS_DO) == LOW;

  bool warning =
    gasValue > 450 &&
    tempValue > 50 &&
    distance < 10;

  if (danger)
  {
    lcd.setCursor(0, 0);
    lcd.print("DANGER");

    lcd.setCursor(0, 1);
    lcd.print("SAFETY STOP");

    return;
  }

  if (warning)
  {
    lcd.setCursor(0, 0);
    lcd.print("WARNING");

    lcd.setCursor(0, 1);
    lcd.print("CHECK SYSTEM");

    return;
  }

  if (!lcdScreen)
  {
    lcd.setCursor(0, 0);
    lcd.print("SYSTEM: ");

    if (systemRunning)
    {
      lcd.print("RUNNING");
    }
    else
    {
      lcd.print("STOPPED");
    }

    lcd.setCursor(0, 1);

    if (motorDirection)
    {
      lcd.print("DIR: FORWARD");
    }
    else
    {
      lcd.print("DIR: REVERSE");
    }
  }
  else
  {
    lcd.setCursor(0, 0);
    lcd.print("G:");
    lcd.print(gasValue);

    lcd.print(" T:");
    lcd.print(tempValue);

    lcd.setCursor(0, 1);
    lcd.print("D:");
    lcd.print((int)distance);

    lcd.print(" S:");
    lcd.print(speedValue);
  }
}

void setup()
{
  pinMode(EMERGENCY_BUTTON, INPUT_PULLUP);

  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  pinMode(BUZZER, OUTPUT);
  pinMode(GAS_DO, INPUT);

  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);

  pinMode(START_BUTTON, INPUT_PULLUP);

  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);

  digitalWrite(STEP_PIN, LOW);
  digitalWrite(DIR_PIN, HIGH);

  gateServo.attach(SERVO_PIN);
  gateServo.write(0);

  lcd.begin(16, 2);

  attachInterrupt(
    digitalPinToInterrupt(EMERGENCY_BUTTON),
    emergencyStop,
    FALLING
  );
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("SMART FACTORY");

  lcd.setCursor(0, 1);
  lcd.print("SYSTEM READY");

  delay(1500);

  lcd.clear();
}

void loop()
{
  unsigned long currentTime = millis();

  bool startButtonState = digitalRead(START_BUTTON);

  if (
    startButtonState == LOW &&
    currentTime - lastButtonTime > 300
  )
  {
    lastButtonTime = currentTime;

    if (!emergency)
    {
      if (!systemRunning)
      {
        systemRunning = true;
      }
      else
      {
        motorDirection = !motorDirection;
      }

      noTone(BUZZER);
    }
  }

  if (currentTime - lastSensorTime >= 200)
  {
    lastSensorTime = currentTime;

    gasValue = analogRead(GAS_AO);

    int rawTemp = analogRead(TEMP_SENSOR);
    tempValue = map(rawTemp, 0, 1023, 0, 100);

    speedValue = analogRead(POT);
    speedValue = map(speedValue, 0, 1023, 0, 255);

    distance = readDistance();
  }

  if (emergency)
  {
    showDanger();
  }
  else if (
    gasValue > 700 &&
    tempValue > 70 &&
    digitalRead(GAS_DO) == LOW
  )
  {
    showDanger();

    systemRunning = false;
  }
  else if (
    gasValue > 450 &&
    tempValue > 50 &&
    distance < 10
  )
  {
    showWarning();
  }
  else
  {
    showNormal();
  }

  controlStepper();

  if (currentTime - lastLcdTime >= 2000)
  {
    lastLcdTime = currentTime;

    lcdScreen = !lcdScreen;

    updateLCD();
  }
}
